/**
 * Photo slugs for the landing-page industry cards: /images/industry-<slug>.jpg,
 * generated by scripts/hf_assets.py images. Plain module so both the server page
 * (which checks which files exist) and the client section can import it.
 */
export const INDUSTRY_PHOTOS = ["home-services", "clinic", "salon", "legal", "real-estate", "events"] as const;

export type IndustryPhoto = (typeof INDUSTRY_PHOTOS)[number];
